/** 두루마리 안의 사진 한 장에 대한 문단과 반응 수를 저장합니다. 인용한 원문은 ParagraphSource로 따로 저장한다. */
package com.dandimate.durooduroo.scroll.domain;
import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="paragraphs") public class Paragraph { @Id private String id; @Column(nullable=false) private String roomId; @Column(nullable=false) private String scrollId; @Column(nullable=false) private String photoId; @Column(nullable=false) private int displayOrder; @Lob @Column(nullable=false) private String body; @Column(nullable=false) private int version; @Column(nullable=false) private int ahMatdaCount; @Column(nullable=false) private LocalDateTime createdAt; protected Paragraph(){} private Paragraph(String r,String s,String p,int order,String b){id=UUID.randomUUID().toString();roomId=r;scrollId=s;photoId=p;displayOrder=order;body=b;version=1;createdAt=LocalDateTime.now();} public static Paragraph create(String roomId,String scrollId,String photoId,int displayOrder,String body){return new Paragraph(roomId,scrollId,photoId,displayOrder,body);} public void updateAhMatdaCount(long count){ahMatdaCount=(int)count;} /** 답가 반영·복구로 본문이 바뀌면 version이 오른다. */ public void revise(String body){this.body=body;this.version++;} public String getId(){return id;} public String getRoomId(){return roomId;} public String getScrollId(){return scrollId;} public String getPhotoId(){return photoId;} public int getDisplayOrder(){return displayOrder;} public String getBody(){return body;} public int getVersion(){return version;} public int getAhMatdaCount(){return ahMatdaCount;} public LocalDateTime getCreatedAt(){return createdAt;} }
